  if v==G and not(cc==3 and rr==2 and bb==2):continue
  zz=(v,cc,rr,bb,mm,tt)
  if zz not in par:par[zz]=z;act[zz]=ch;q.append(zz)
print('found',end,'states',len(par))
if end:
 aa=[];zzs=[];cur=end
 while par[cur] is not None:aa.append(act[cur]);zzs.append(cur);cur=par[cur]
 aa=aa[::-1];zzs=zzs[::-1]
 print('len',len(aa),'seq',''.join(aa))
 for i,(ch,z) in enumerate(zip(aa,zzs),1):
  p,cp,rp,bp,m,t=z;ev=[]
  if p==C:ev.append('C'+str(cp))
  if p==R:ev.append('R'+str(rp))
  if p in Qs:ev.append('Q'+str(Qs.index(p)+1))
  if p==G:ev.append('G')
